UPDATE courses SET
    course_description = '<div class="elementor-widget-container"> <p>Advanced Diploma of Business reflects the role of individuals in a variety of Business Services job roles. These individuals may have general management accountabilities.</p> <p>Individuals in these roles carry out complex tasks in a specialist field of expertise. They may undertake technical research and analysis, and will often contribute to setting the strategic direction for a work area.</p> <p>The qualification is suited to individuals who are responsible for the supervision and leadership of a team or work area (including by managing staff performance and making staffing decisions).</p> </div>',
    total_course_duration = '52 Weeks',
    offshore_tuition_fee = '15000',
    entry_requirements = '<div class="elementor-widget-container"> <p>To be considered for enrolment, applicants must:</p> <ul style="margin-left: 25px"> <li>Be at least 18 years of age.</li> <li>Have completed at least the equivalent of Year 12.</li> <li>Have an IELTS Academic score of 6.0 with test results no more than 2 years old.</li> <li>Complete a Core Skills Check. <p><em>Note: Applicants identified as at risk will be required to complete a full LLND assessment and a Course Pre-Entry Review (including an interview where required) to confirm their suitability before enrolment.</em></p></li> <li>Have access to a computer or laptop with a reliable internet connection, webcam, and microphone, to complete online learning, assessments, and Learning Management System (LMS) requirements.</li> </ul> <p><em style="display: block;padding-top:24px">Applicants do not need to provide IELTS (or equivalent) results if they can provide documented evidence of either:</em></p> <ul style="margin-left: 25px"> <li>Completion of at least 6 months of a Certificate IV level course at an Australian RTO, or</li> <li>Successful completion of a Brighton College English Placement Test.</li> </ul> <p><em style="display: block;padding-top:24px">Note: Other recognised English tests (e.g. PTE Academic, TOEFL) can be accepted. Applicants must provide their results so equivalence to IELTS Academic 6.0 can be confirmed.</em></p> </div>',
    apply_form = 'https://brighton.edu.au/courses/advanced-diploma-of-business/',
    updated_at = NOW()
WHERE cricos_course_code = '105065K';
UPDATE courses SET
    course_description = '<div class="elementor-widget-container"> <p class="ait4">This qualification reflects the role of highly skilled senior managers who use a broad range of hospitality skills combined with specialised managerial skills and substantial knowledge of industry to coordinate hospitality operations. They operate with significant autonomy and are responsible for making strategic business management decisions.</p> <p class="ait4">This qualification provides a pathway to work in any hospitality industry sector and for a diversity of employers including restaurants, hotels, motels, catering operations, clubs, pubs, cafés, and coffee shops. This qualification allows for multi-skilling and for acquiring targeted skills in accommodation services, cookery, food and beverage and gaming.</p> </div>',
    total_course_duration = '104 Weeks',
    offshore_tuition_fee = '15500',
    entry_requirements = '<div class="elementor-widget-container"> <p>To be considered for enrolment, applicants must:</p> <ul style="margin-left: 25px"> <li>Be at least 18 years of age.</li> <li>Have completed at least the equivalent of Year 12.</li> <li>Have an IELTS Academic score of 6.0 with test results no more than 2 years old.</li> <li>Complete a Core Skills Check.<br/> <em>Note: Applicants identified as at risk will be required to complete a full LLND assessment and a Course Pre-Entry Review (including an interview where required) to confirm their suitability before enrolment.</em></li> <li>Have access to a computer or laptop with a reliable internet connection, webcam, and microphone, to complete online learning, assessments, and Learning Management System (LMS) requirements.</li> </ul> <p><em style="display: block;padding-top: 24px">Applicants do not need to provide IELTS (or equivalent) results if they can provide documented evidence of either:</em></p> <ul style="margin-left: 25px"> <li>Completion of at least 6 months of a Certificate IV level course at an Australian RTO, or</li> <li>Successful completion of a Brighton College English Placement Test.</li> </ul> <p><em style="display: block;padding-top:24px">Note: Other recognised English tests (e.g. PTE Academic, TOEFL) can be accepted. Applicants must provide their results so equivalence to IELTS Academic 6.0 can be confirmed.</em></p> </div>',
    apply_form = 'https://brighton.edu.au/courses/advanced-diploma-of-hospitality-management/',
    updated_at = NOW()
