UPDATE courses SET
    course_description = '<div class="elementor-widget-container"> <p class="RTOWorksBodyText">Advanced Diploma of Information Technology reflects the role of individuals in a variety of information and communications technology (ICT) roles who have significant experience in specialist technical skills, or managerial business and people management skills.</p> <p class="RTOWorksBodyText">Individuals in these roles carry out complex tasks in a specialist field, working independently, leading a team or a strategic direction of a business. They apply their skills across a wide range of industries and business functions, or as a business owner (sole trader/contractor).</p> </div>',
