UPDATE courses SET
    course_description = '<div class="elementor-widget-container"> <p>CHC33021 Certificate III in Individual Support reflects the role of workers in the community and/or residential setting who follow an individualized plan to provide person-centered support to people who may require support due to ageing, disability or some other reason. Work involves using discretion and judgement in relation to individual support as well as taking responsibility for own outputs. Workers have a range of factual, technical and procedural knowledge, as well as some theoretical knowledge of the concepts and practices required to provide person-centred support.</p> <p>To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.</p> <p>The latest release of the qualification can be found at: <a href="https://training.gov.au/Training/Details/CHC33021" rel="noopener" target="_blank">https://training.gov.au/Training/Details/CHC33021</a></p> </div>',
    total_course_duration = '45 Weeks',
    offshore_tuition_fee = '16000',
    entry_requirements = '<div class="elementor-widget-container"> <p>To be considered for enrolment, applicants must:</p> <ul style="margin-left: 25px"> <li>Be at least 18 years of age.</li> <li>Have completed at least the equivalent of Year 11.</li> <li>Have an IELTS Academic score of 6.0 (or equivalent), with test results no more than 2 years old.</li> <li>Complete a Core Skills Check.<br/> <em>Note: Applicants identified as at risk will be required to complete a full LLND assessment and a Course Pre-Entry Review (including an interview where required) to confirm their suitability before enrolment.</em></li> <li>Have access to a computer or laptop with a reliable internet connection, webcam, and microphone, to complete online learning, assessments, and Learning Management System (LMS) requirements.</li> </ul> <p><em style="display: block;padding-top: 24px">Applicants do not need to provide IELTS (or equivalent) results if they can provide documented evidence of either:</em></p> <ul style="margin-left: 25px"> <li>Completion of at least 6 months of a Certificate III level course at an Australian RTO, or</li> <li>Successful completion of a Brighton College English Placement Test.</li> </ul> <p><em style="display: block;padding-top: 24px">Note: Other recognised English tests (e.g. PTE Academic, TOEFL) can be accepted. Applicants must provide their results so equivalence to IELTS Academic 6.0 can be confirmed.</em></p> </div>',
    apply_form = 'https://brighton.edu.au/courses/certificate-iii-in-individual-support/',
    updated_at = NOW()
WHERE cricos_course_code = '112949D';
UPDATE courses SET
    course_description = '<div class="elementor-widget-container"> <p>Certificate IV in Ageing Support reflects the role of support workers who complete specialised tasks and functions in aged services; either in residential, home or community-based environments. Workers will take responsibility for their own outputs within defined organisation guidelines and maintain quality service delivery through the development, facilitation and review of individualized service planning and delivery.</p> <p>Workers may be required to demonstrate leadership and have limited responsibility for the organisation and the quantity and quality of outputs of others within limited parameters.</p> <p>To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.</p> <p>The latest release of the qualification can be found at: <a href="https://training.gov.au/Training/Details/CHC43015" rel="noopener" target="_blank">https://training.gov.au/Training/Details/CHC43015</a></p> </div>',
