UPDATE courses SET
    course_description = '<div class="elementor-widget-container"> <p>CHC52025 Diploma of Community services reflects the roles of community services, case management and social housing workers involved in managing, coordinating and/or delivering person-centered services to individuals, groups and communities.</p> <p>At this level, workers have specialized skills in community services and work autonomously under broad directions from senior management. Workers are usually providing direct support to individuals or groups of individuals. Workers may also have responsibility for the supervision of other workers and volunteers and/or case management; program coordination or the development of new business opportunities.</p> <p>The latest release of the qualification can be found at <a href="https://training.gov.au/Training/Details/CHC52025" rel="noopener" target="_blank">https://training.gov.au/Training/Details/CHC52025</a></p> </div>',
