UPDATE courses SET
    course_description = '<div class="elementor-widget-container"> <p>The English for Academic Purposes (EAP) course is designed to prepare international students, from a range of backgrounds and nationalities, to undertake tertiary study in Australia.</p> <p>Students enrolled for this course will have as their specific study objective the completion of a tertiary level course in an Australian tertiary institution.</p> <p>The focus of this EAP course is developing the skills areas in English, which the student will require to study alongside native speakers in tertiary courses. However, students entering the EAP course at the lower level will not necessarily have access to the language base, which makes the use of these skills a possibility. For this reason the balance of the EAP course will move systematically from a language focus to a skills focus as the student progresses through the levels from EAP Level 1 to EAP Level 2.</p> </div>',
    total_course_duration = '26 Weeks',
    offshore_tuition_fee = '9100',
    entry_requirements = '<div class="elementor-widget-container"> <p>There are no specific educational pre-requisites for entry into this course, as entry into this level is based on assessment of English language proficiency. However, it is anticipated that a majority of students will have completed Year 10 or equivalent.</p> <p>Successful completion of Intermediate level or above of the General English course will permit admission to the EAP Level 1.</p> <p>Successful completion of Upper Intermediate level or above of the General English course or EAP Level 1 course will permit admission to the EAP Level 2</p> <p>The acceptable level in international tests required for entry to the courses is outlined below</p> <ul> <li>IELTS Band 5.0 with no band &lt; 4.5 = EAP Level 1</li> <li>IELTS Band 5.5 with no band &lt; 5.0 = EAP Level 2</li> </ul> </div>',
    apply_form = 'https://brighton.edu.au/courses/english-for-academic-purposes/',
    updated_at = NOW()
WHERE cricos_course_code = '111960F';
UPDATE courses SET
    course_description = '<div class="elementor-widget-container"> <p>The General English course is designed to prepare students for conversation, everyday situations and daily interactions that take place when travelling or living in an English-speaking country. Students learn and practice skills such as listening, reading, writing, and speaking in an interactive environment. Students commence at the level according to their current ability. Levels of difficulty increase over the duration of the course to assist students develop their skills and to be more confident and fluent in English.</p> <p>Successful completion of this course may allow the student to study other ELICOS courses such as English for Academic Purposes or Vocational Education and Training or Higher Education courses.</p> </div>',
    total_course_duration = '78 Weeks',
    offshore_tuition_fee = '27300',
    entry_requirements = '<div class="elementor-widget-container"> <p>International students must be at least 18 years of age.</p> <p>There are no specific educational pre-requisites for entry into this course, as entry into this level is based on assessment of English language proficiency. However, it is anticipated that a majority of students will have completed Year 10 or equivalent.</p> <p>Students will be assessed at orientation using the Oxford Placement Test and an interview.</p> <p>The appropriate class level requirements is shown in the table below:</p> <table> <tbody> <tr> <td>Starter Level</td> <td colspan="2">No minimum entry requirements</td> <td></td> </tr> <tr> <td rowspan="3">Elementary Level</td> <td>CEFR Level</td> <td>A1</td> </tr> <tr> <td>PTE Academic</td> <td>Not Applicable</td> </tr> <tr> <td>IELTS</td> <td>Not Applicable</td> </tr> <tr> <td rowspan="3">Pre-Intermediate Class Level</td> <td>CEFR Level</td> <td>A2</td> </tr> <tr> <td>PTE Academic</td> <td>Not Applicable</td> </tr> <tr> <td>IELTS</td> <td>Not Applicable</td> </tr> <tr> <td rowspan="3">Intermediate Class Level</td> <td>CEFR Level</td> <td>B1</td> </tr> <tr> <td>PTE Academic</td> <td>36-43</td> </tr> <tr> <td>IELTS</td> <td>4-5</td> </tr> <tr> <td rowspan="3">Upper-Intermediate Class Level</td> <td>CEFR level</td> <td>B2</td> </tr> <tr> <td>PTE Academic</td> <td>50-58</td> </tr> <tr> <td>IELTS</td> <td>5.5-6.5</td> </tr> <tr> <td rowspan="3">Advanced class level</td> <td>CEFR level</td> <td>C1</td> </tr> <tr> <td>PTE Academic</td> <td>73-79</td> </tr> <tr> <td>IELTS</td> <td>7-8</td> </tr> </tbody> </table> </div>',
    apply_form = 'https://brighton.edu.au/courses/general-english/',
    updated_at = NOW()
WHERE cricos_course_code = '111959K';
UPDATE courses SET
    course_description = '<div class="elementor-widget-container"> <p class="ait4">This qualification reflects the role of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others.</p> <p class="ait4">This qualification may apply to leaders and managers in an organisation where learning is used to build organisational capability. The job roles that relate to this qualification may also include RTO Manager and RTO Director.</p> </div>',
    total_course_duration = '52 Weeks',
    offshore_tuition_fee = '15500',
    entry_requirements = '<div class="elementor-widget-container"> <p>To be considered for enrolment, applicants must:</p> <ul style="margin-left: 25px"> <li>Be at least 18 years of age.</li> <li>Have completed at least the equivalent of an AQF Level 5 or higher, or equivalent of a three (3) year bachelor’s degree overseas.</li> <li>Have an IELTS Academic score of 6.5 (or equivalent), with test results no more than 2 years old.</li> <li>Complete a Core Skills Check.<br/> <em>Note: Applicants identified as at risk will be required to complete a full LLND assessment and a Course Pre-Entry Review (including an interview where required) to confirm their suitability before enrolment.</em></li> <li>Have access to a computer or laptop with a reliable internet connection, webcam, and microphone, to complete online learning, assessments, and Learning Management System (LMS) requirements.</li> </ul> <p><em style="display: block;padding-top:24px">Applicants do not need to provide IELTS (or equivalent) results if they can provide documented evidence of either:</em></p> <ul style="margin-left: 25px"> <li>Completion of at least 6 months of a Diploma level course at an Australian RTO, or</li> <li>Successful completion of a Brighton College English Placement Test.</li> </ul> <p><em style="display: block;padding-top:24px">Note: Other recognised English tests (e.g. PTE Academic, TOEFL) can be accepted. Applicants must provide their results so equivalence to IELTS Academic 6.5 can be confirmed.</em></p> </div>',
    apply_form = 'https://brighton.edu.au/courses/graduate-diploma-of-managementlearning/',
    updated_at = NOW()
WHERE cricos_course_code = '105059H';
UPDATE courses SET
    course_description = '<div class="elementor-widget-container"> <p>The Pearson Test of English (PTE) Examination Preparation course has been designed for students seeking to acquire the language and test taking skills required to undertake the PTE. This course specifically prepares students for the Pearson Test of English (PTE) at Level 1 (B1) Examination. The PTE is recognised by many universities, employers and governments around the world.</p> <p>The PTE course is made up of 10 units of study, each of which is delivered over a week. It teaches reading, writing, listening and speaking skills which are necessary for the exam how to approach each exam task, as well as essential grammar and vocabulary.</p> </div>',
    total_course_duration = '39 Weeks',
    offshore_tuition_fee = '13650',
    entry_requirements = '<div class="elementor-widget-container"> <table> <tbody> <tr> <td>ITEM</td> <td colspan="2">NEEDED</td> <td></td> </tr> <tr> <td>Education level requirements</td> <td>There are no specific educational pre-requisites for entry into this course, as entry into this level is based on assessment of English language proficiency. However, it is anticipated that a majority of students will have completed year 10 or equivalent.</td> </tr> <tr> <td>English language requirements</td> <td>IELTS 5.0 or above</td> </tr> <tr> <td>Age requirements</td> <td>18 and above</td> </tr> </tbody> </table> </div>',
    apply_form = 'https://brighton.edu.au/courses/pearson-test-of-english-preparation',
    updated_at = NOW()
WHERE cricos_course_code = '115214H';
